package com.example.agendaescolar;
import android.app.*;import android.content.*;import android.os.Build;import java.util.*;
public class AlarmReceiver extends BroadcastReceiver{
 public void onReceive(Context c,Intent i){String t=i.getStringExtra("title");if(t==null)t="📚 LIBROS";String b=i.getStringExtra("body");if(b==null)b="Revisa los libros que tienes que traer.";NotificationManager n=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);if(Build.VERSION.SDK_INT>=26)n.createNotificationChannel(new NotificationChannel("agenda","Agenda Escolar",NotificationManager.IMPORTANCE_HIGH));Notification.Builder x=Build.VERSION.SDK_INT>=26?new Notification.Builder(c,"agenda"):new Notification.Builder(c);n.notify(i.getIntExtra("id",142020),x.setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle(t).setContentText(b).build());if(i.getBooleanExtra("daily",false))set(c,i.getIntExtra("id",142020),t,b,i.getIntExtra("hour",14),i.getIntExtra("minute",20),true);}
 static void set(Context c,int id,String t,String b,int h,int m,boolean daily){Calendar x=Calendar.getInstance();x.set(Calendar.HOUR_OF_DAY,h);x.set(Calendar.MINUTE,m);x.set(Calendar.SECOND,0);if(x.getTimeInMillis()<=System.currentTimeMillis())x.add(Calendar.DATE,1);Intent i=new Intent(c,AlarmReceiver.class).putExtra("id",id).putExtra("title",t).putExtra("body",b).putExtra("hour",h).putExtra("minute",m).putExtra("daily",daily);int f=PendingIntent.FLAG_UPDATE_CURRENT;if(Build.VERSION.SDK_INT>=23)f|=PendingIntent.FLAG_IMMUTABLE;PendingIntent p=PendingIntent.getBroadcast(c,id,i,f);AlarmManager a=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);if(a!=null)a.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,x.getTimeInMillis(),p);}
 static void defaults(Context c){set(c,142020,"📚 LIBROS","Revisa los libros que tienes que traer.",14,20,true);}
}